def transform(grid):
    a=[row[:] for row in grid]
    colors={v for row in grid for v in row}
    bg=max(colors,key=lambda x:sum(row.count(x) for row in grid))
    fg=next(v for v in colors if v!=bg)
    h,w=len(grid),len(grid[0])
    for r in range(h):
        cs=[c for c in range(w) if grid[r][c]==fg]
        if len(cs)>1:
            for c in range(min(cs),max(cs)+1):
                if a[r][c]==bg:a[r][c]=2
    for c in range(w):
        rs=[r for r in range(h) if grid[r][c]==fg]
        if len(rs)>1:
            for r in range(min(rs),max(rs)+1):
                if a[r][c]==bg:a[r][c]=2
    return a

